args.old_str:
FLOAT R_GetFontWidth(LPFONT font, LPCSTR text) {
    FLOAT x = 0;
    LPCSTR p = text;
    unsigned codepoint;
    while (*p) {
        p = utf8_to_codepoint(p, &codepoint);
        glyphSet_t *set = R_GetGlyphSet(font, codepoint);
        stbtt_bakedchar *g = &set->glyphs[codepoint & 0xff];
        x += INV_SCALE_X(g->xadvance);
    }
    return x;
}

args.new_str:
FLOAT R_GetFontWidth(LPFONT font, LPCSTR text) {
    FLOAT x = 0;
    LPCSTR p = text;
    unsigned codepoint;
    while (*p) {
        p = utf8_to_codepoint(p, &codepoint);

        // 计算宽度不需要纹理，传入 FALSE
        glyphSet_t *set = R_GetGlyphSet(font, codepoint, FALSE);
        stbtt_bakedchar *g = &set->glyphs[codepoint & 0xff];

        // 检查 glyph 是否有效
        if (g->x1 > g->x0) {
            x += INV_SCALE_X(g->xadvance);
        } else {
            // 使用默认宽度
            x += INV_SCALE_X(font->size * 0.5);
        }
    }
    return x;
}
